pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 d, uint256 m) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d > 0);
        vm.assume(m <= d);
        vm.assume(address(this).balance >= d);
        try c.SetMinSum(m) {} catch { return; }
        uint256 bal0;
        try c.balances(address(this)) returns (uint256 __r) { bal0 = __r; } catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
        uint eth0 = address(c).balance;
        bool reverted;
        try c.Collect(d) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == bal0 && address(c).balance == eth0 - d);
    }

    function testFuzz_run(uint256 d, uint256 m) public {
        _run(d, m);
    }

    receive() external payable {}
}
